window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"qLTigVu8VJI","speaker":"Aleksandar Vučić","role":"President","country":"Serbia","region":"Europe","url":"https://www.youtube.com/watch?v=qLTigVu8VJI","date":"20260923","title":"🇷🇸 Serbia - President Addresses United Nations General Assembly 81st Session | #UNGA","seconds":1220,"words":3143,"counts":{"claims":39,"promises":2,"attacks":8},"topics":[{"topic":"UN reform","share":0.2185,"seconds":267},{"topic":"Kosovo status","share":0.1627,"seconds":199},{"topic":"Global order","share":0.1108,"seconds":135},{"topic":"EU enlargement","share":0.0654,"seconds":80},{"topic":"NATO aggression","share":0.0628,"seconds":77},{"topic":"Serbia hosting","share":0.0579,"seconds":71},{"topic":"Croatia politics","share":0.0578,"seconds":71},{"topic":"Serbia US relations","share":0.0559,"seconds":68},{"topic":"Ukraine war","share":0.0555,"seconds":68},{"topic":"China relations","share":0.0521,"seconds":64},{"topic":"Serbia EU integration","share":0.0509,"seconds":62},{"topic":"Serbia technology","share":0.0496,"seconds":60}],"timeline":[[3,68,"UN reform"],[70,141,"Global order"],[142,214,"UN reform"],[215,283,"Ukraine war"],[284,347,"Kosovo status"],[348,425,"NATO aggression"],[426,494,"Serbia US relations"],[495,566,"Croatia politics"],[567,631,"Kosovo status"],[632,703,"Kosovo status"],[704,766,"Serbia EU integration"],[767,847,"EU enlargement"],[848,912,"China relations"],[913,983,"UN reform"],[984,1044,"UN reform"],[1044,1105,"Serbia technology"],[1105,1170,"Global order"],[1170,1241,"Serbia hosting"]],"stances":{"UN reform":"Aleksandar Vučić agrees on the need to restore trust in the United Nations but expresses uncertainty regarding the extent of a transformation that has already occurred.","Global order":"Aleksandar Vučić states that the previous international system has collapsed and is being replaced by a new, complex order with two main power centers and strong regional actors, leading to increased risks of conflict through various non-conventional means.","Ukraine war":"Aleksandar Vučić argues that powerful countries hypocritically demand adherence to international law regarding Ukraine while having previously violated the same principles when they held power.","Kosovo status":"Aleksandar Vučić asserts that countries recognizing Kosovo's unilateral declaration of independence have violated international law and destroyed the order based on the UN Charter.","NATO aggression":"Aleksandar Vučić asserts that the NATO attack on Serbia was unjustified, intended to destroy the post-WWII UN order and confirm Western dominance, while noting no humanitarian disaster occurred.","Serbia US relations":"Vučić states that Serbia supports the Trump administration's actions as an opportunity for a more just world order and views itself as a close American ally, while asserting that past attempts to defeat Serbia failed.","Croatia politics":"Aleksandar Vučić states that moral lectures from Croatia are unacceptable due to the resurgence of Nazism and the use of Nazi symbols in the country.","Serbia EU integration":"Aleksandar Vučić states that Serbia remains committed to its European path despite enlargement fatigue and acknowledges the difficulty of maintaining a principled position, while expressing gratitude for EU assistance.","EU enlargement":"Aleksandar Vučić argues that Serbia expects tangible results from its EU accession process and proposes integrating the Western Balkans into the EU single market and Schengen area as a pragmatic solution to the current deadlock, while maintaining traditional friendships with other global powers.","China relations":"Vučić expresses gratitude for Chinese support and hopes for productive talks between the Chinese president and President Trump to stabilize global developments.","Serbia technology":"Aleksandar Vučić states that Serbia prioritized connecting technological progress with security, human rights, and the rule of law during its 2025 chairmanship of the global partnership on artificial intelligence.","Serbia hosting":"Vučić expresses anticipation for the upcoming event in Belgrade and emphasizes that trust is built through concrete actions rather than declarations."},"claims":[{"t":43,"quote":"the theme of this year's session, restoring trust, managing A United Nations that delivers for all captures at least in part the moment in which we find ourselves.","topic":"UN reform","kind":"fact"},{"t":57,"quote":"I agree that we need to restore trust in the United Nations","topic":"UN reform","kind":"fact"},{"t":70,"quote":"The international system as we knew it has collapsed. It no longer exists.","topic":"Global order","kind":"fact"},{"t":75,"quote":"Today we are witnessing the emergence of a new order increasingly structured around two principal centers of power alongside a growing number of strong regional actors","topic":"Global order","kind":"fact"},{"t":98,"quote":"We are therefore entering a period marked by a more complex and less predictable distribution of power in which the risk of potential conflict is greater than it has been for decades.","topic":"Global order","kind":"fact"},{"t":181,"quote":"The traditional system of international justice is seriously undermined whenever interests prevail over law and the same rules do not apply to everyone.","topic":"UN reform","kind":"fact"},{"t":191,"quote":"The greatest problem of today is not a lack of rules or political principles but the fact that they were not respected in the past or now.","topic":"UN reform","kind":"fact"},{"t":220,"quote":"the fact that in the past we tore down and violated that charter by which we opened the Pandora's box","topic":"Ukraine war","kind":"fact"},{"t":242,"quote":"How many times over the past two days from this roast roomm have you heard calls and appeals for observance of the principles of international public law?","topic":"Ukraine war","kind":"number"},{"t":295,"quote":"attempted to seize 14% of the territory of the Republic of Serbia","topic":"Kosovo status","kind":"number"},{"t":312,"quote":"order based on respect for the UN charter and the law founded upon it no longer exists. It was destroyed by those who tore apart the territories of other countries","topic":"Kosovo status","kind":"fact"},{"t":358,"quote":"The humanitarian disaster did not occur. and I have still not managed to hear or see where a similar example has occurred anywhere in the world.","topic":"NATO aggression","kind":"fact"},{"t":401,"quote":"not a single soldier, not a single police officer from Serbia had set foot on the territory of any other country.","topic":"NATO aggression","kind":"fact"},{"t":432,"quote":"such a decision was never made in the first place. And to make things even worse, no one ever even attempted to make such a decision.","topic":"Serbia US relations","kind":"fact"},{"t":439,"quote":"They were so arrogant and so powerful that they trampled everything in their path from the Clinton administration to the administration of numerous European countries.","topic":"Serbia US relations","kind":"fact"},{"t":450,"quote":"That is precisely why Serbia supports the actions of the administration of President Donald Trump and sees in his work an opportunity for establishing a more just order in the world and more responsible attitude towards Serbia as a close American ally from both world wars.","topic":"Serbia US relations","kind":"fact"},{"t":470,"quote":"They trampled Serbia, but they did not defeat it. Serbia rose like a phoenix from the ashes.","topic":"Serbia US relations","kind":"fact"},{"t":525,"quote":"The most difficult thing for us in Serbia is when we see in our surroundings the resurgence of Nazism elevated to the position of social prominence, especially in the Republic of Croatia","topic":"Croatia politics","kind":"fact"},{"t":536,"quote":"which is proud of its Nazi past and one and of the use of Nazi slogans and symbols today","topic":"Croatia politics","kind":"fact"},{"t":542,"quote":"The Serbian people as people who suffer the most from Nazi hands cannot accept the revival of the most terrible ghosts from the past responsible for the death of hundreds of thousands of Serbs, Jews and Roma in mon in monstrous concentration camps like","topic":"Croatia politics","kind":"fact"},{"t":568,"quote":"for four and a half years now, I have been listening to lectures","topic":"Kosovo status","kind":"fact"},{"t":593,"quote":"territorial integrity of Serbia which is guaranteed by the UN charter and the resolution of the UN SC 1244","topic":"Kosovo status","kind":"fact"},{"t":632,"quote":"That is how we signed the famous Brussels agreement in 12 in 2013, wishing to resolve problems between Serbs and Albanians in Kosovo and Mia by compromise.","topic":"Kosovo status","kind":"fact"},{"t":642,"quote":"All the obligations that were to be met by Serbia have been met and the only one that was to be bet met by Albanians, the one about the establishment of the community of Serb municipalities has not been met to this day.","topic":"Kosovo status","kind":"fact"},{"t":669,"quote":"As the president of Serbia for 10 years, I have been facing all possible tricks and pressures to give up on full implementation of what was signed.","topic":"Kosovo status","kind":"self_credit"},{"t":717,"quote":"Thank you for being consistent in not recognizing the independence of a part of Serbia's territory.","topic":"Serbia EU integration","kind":"fact"},{"t":735,"quote":"We are grateful to the European Union in and in particular to the president of the European Commission Ursula under Lion and to the president of the European Council Antonio Ka for every kind of assistance they have provided to our country.","topic":"Serbia EU integration","kind":"self_credit"},{"t":767,"quote":"We obtained candidates titus in 2012 and opened accession negotiations in 2014, more than 12 years ago.","topic":"EU enlargement","kind":"fact"},{"t":838,"quote":"Belgrade is one of the few European capitals from which one can fly directly to the United States of America, the People's Republic of China and the Russian Federation.","topic":"EU enlargement","kind":"fact"},{"t":848,"quote":"I owe special gratitude for the support during co pandemics as well as for a paramount investment in Serbia to the president of the people's republic of China Cining","topic":"China relations","kind":"fact"},{"t":873,"quote":"with whom we recently marked in Belgrade the 65th anniversary of the first conference of non-aligned countries held in our capital in 1961","topic":"China relations","kind":"fact"},{"t":971,"quote":"Over the past eight decades, states have not come to this building because they share the same interests, but because they understood that the cost of settling disagreements by force of arms was too high.","topic":"UN reform","kind":"fact"},{"t":1037,"quote":"Artificial intelligence is already changing the economy, education, medicine, security, the labor market, and the way states function.","topic":"UN reform","kind":"fact"},{"t":1057,"quote":"During our during our leadership cycle in the global partnership of artificial intelligence which Serbia chaired in 2025","topic":"Serbia technology","kind":"fact"},{"t":1077,"quote":"The Belgrade Ministerial Declaration received the support of 44 member states and the European Union","topic":"Serbia technology","kind":"number"},{"t":1112,"quote":"technological progress will not make the world safer. It will merely make us more technologically advanced in a world that is becoming politically less predictable.","topic":"Global order","kind":"fact"},{"t":1132,"quote":"the sovereign equality of states, respect for territorial integrity, the prohibition of the use of forces except in the cases expressly provided for in the UN charter and the obligation not to change the rules from one case to another.","topic":"Global order","kind":"fact"},{"t":1170,"quote":"Cultures, science, sport, technology, business and young people from all parts of the world will come together in Belgrade","topic":"Serbia hosting","kind":"fact"},{"t":1199,"quote":"Serbia endeavors to do so by preserving peace in its neighborhood, participating in peacekeeping missions far from its borders, assisting others when they are in danger, speaking even with those with whom it disagrees, and fulfilling the commitments it undertakes","topic":"Serbia hosting","kind":"self_credit"}],"promises":[{"t":622,"quote":"And I want to warn all of you, all of you here who belong to the global south, pay the utmost attention while signing all the agreements with great powers.","topic":"Kosovo status","kind":"threat"},{"t":683,"quote":"In spite of everything, Serbia will defend its country, its territorial integrity, the UN charter, the UN Security Council resolution 1244.","topic":"Kosovo status","kind":"promise"}],"attacks":[{"t":238,"quote":"powerful and great countries trampled so brutally","topic":"Ukraine war","target":"Western nations"},{"t":256,"quote":"majority of those same countries shamelessly and recklessly remain silent about the fact that they themselves participated in trampling the charter","topic":"Ukraine war","target":"Western nations"},{"t":319,"quote":"those who tore apart the territories of other countries for the sake of their own political and economic interests. They did so unscrupulously, recklessly","topic":"Kosovo status","target":"Western nations"},{"t":366,"quote":"The attack against the small yet free and freedomloving country Serbia of which I am the proud president was carried out with the intention of finally destroying the UN order established after the world world warn and of formally and informally confirming the dominance of at that time unison western world of United States of America and Europe.","topic":"NATO aggression","target":"Western nations"},{"t":439,"quote":"They were so arrogant and so powerful that they trampled everything in their path from the Clinton administration to the administration of numerous European countries.","topic":"Serbia US relations","target":"Western nations"},{"t":486,"quote":"Nevertheless, the consequences of that brutal attack against Serbia are enormous and particularly visible here in the UN General Assembly.","topic":"Serbia US relations","target":"Western nations"},{"t":534,"quote":"especially in the Republic of Croatia, which is proud of its Nazi past and one and of the use of Nazi slogans and symbols today","topic":"Croatia politics","target":"Croatia"},{"t":572,"quote":"How many in the west remain last beacon of democracy in the world, the protectors not of Ukraine's but of the rules and principles of international law. And when they raise the their voices thinking that they are being highly moral and that their positions are the only right ones, we simply smile and ask ourselves. And how did you treat Kosovo and MKI and the territorial integrity of Serbia","topic":"Kosovo status","target":"Western nations"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":3,"topic":"UN reform","text":"The assembly will hear an address by His Excellency Alexander Vhuch, President of the Republic of Serbia. I request protocol to escort his excellency and I invite is him to address the assembly. Mr. President of the General Assembly, excellencies, ladies and gentlemen, the theme of this year's session, restoring trust, managing A United Nations that delivers for all captures at least in part the moment in which we find ourselves. I agree that we need to restore trust in the United Nations, but I'm less certain about the extent to which we can manage a transformation that has in many respects already taken place."},{"t":70,"topic":"Global order","text":"The international system as we knew it has collapsed. It no longer exists. Today we are witnessing the emergence of a new order increasingly structured around two principal centers of power alongside a growing number of strong regional actors with considerable political, economic, military and technological capabilities seeking to shape their own environments and influence broader global developments on their own terms. We are therefore entering a period marked by a more complex and less predictable distribution of power in which the risk of potential conflict is greater than it has been for decades. There is no longer confined to conf to conventional armed conflicts between states. Confrontations are increasingly taking the form of economic pressure, technological restrictions, competition for resources and market cyber attacks, disinformation, and attempts to influence other societies. Cultural and identity based divisions are also becoming more pronounced, increasingly exploited for political purposes, and further deepening mistrust among peoples."},{"t":142,"topic":"UN reform","text":"The boundary between peace and conflict is becoming ever less distinct. While the consequences of confrontation among global and regional powers increasingly affect even those countries that are not directly involved for small and medium-sized countries just like the Republic of Serbia, such an environment represents an enormous challenge. The space for independent decision making is narrowing while pressure on states to choose sides is steadily increasing. At the same time, disagreements among the most powerful actors are increasingly paralyzing the very institutions that should be protecting all countries equally. The traditional system of international justice is seriously undermined whenever interests prevail over law and the same rules do not apply to everyone. The greatest problem of today is not a lack of rules or political principles but the fact that they were not respected in the past or now. You will notice, dear friends, that today, with the exception of a few countries, everyone speaks of and invokes the UN charter, the spirit of the charter, and the principles on which the world order that was enforced until recently was based on."},{"t":215,"topic":"Ukraine war","text":"It is as though they want to tell us never mind it doesn't count. That the fact that in the past we tore down and violated that charter by which we opened the Pandora's box which is impossible to be closed and today we would like without consequences to return to the future. They would like to revitalize the observance of the very same principles that powerful and great countries trampled so brutally. How many times over the past two days from this roast roomm have you heard calls and appeals for observance of the principles of international public law? Particularly when it comes to the conflict in Ukraine. While the majority of those same countries shamelessly and recklessly remain silent about the fact that they themselves participated in trampling the charter and destroying the foundations of the international public law system. And today they would at any cost like to return to those principles now that they see that more powerful and stronger ones have resorted to the very same violations that they themselves carried out when they were the most powerful and the strongest."},{"t":284,"topic":"Kosovo status","text":"Here I'm referring to all the countries that recognize the unilaterally declared independence of the so-called Kosovo and without any basis whatsoever in international legal documents attempted to seize 14% of the territory of the Republic of Serbia. To many of you this may sound like a distant past, but the wounds inflicted on international public law are becoming ever deeper and more severe. To be completely precise, the order based on respect for the UN charter and the law founded upon it no longer exists. It was destroyed by those who tore apart the territories of other countries for the sake of their own political and economic interests. They did so unscrupulously, recklessly and Do you know do you know esteemed friends what was in fact the reason the sole official and formal reason for the attack on the territory of the Republic of Serbia and the Federal Republic of Yugoslavia carried out by 19 NATO countries."},{"t":348,"topic":"NATO aggression","text":"You will not believe it. They told us that they had attacked a sovereign, free and independent country in order to prevent a potential humanitarian disaster. The humanitarian disaster did not occur. and I have still not managed to hear or see where a similar example has occurred anywhere in the world. The attack against the small yet free and freedomloving country Serbia of which I am the proud president was carried out with the intention of finally destroying the UN order established after the world world warn and of formally and informally confirming the dominance of at that time unison western world of United States of America and Europe. Do you know which countries, dear friends, took part in decision making in the UN Security Council to bomb an independent and sovereign country that had attacked no other country? Just to add, not a single soldier, not a single police officer from Serbia had set foot on the territory of any other country. And yet the decision was made. I'm certain that most of you, dear friends, who are among those best informed about world politics, no longer remember much of these either and especially not the fact of who in the UN SC voted for that decision or perhaps in the general assembly."},{"t":426,"topic":"Serbia US relations","text":"Do not even try because it is impossible for you to remember. Why? Because such a decision was never made in the first place. And to make things even worse, no one ever even attempted to make such a decision. They were so arrogant and so powerful that they trampled everything in their path from the Clinton administration to the administration of numerous European countries. That is precisely why Serbia supports the actions of the administration of President Donald Trump and sees in his work an opportunity for establishing a more just order in the world and more responsible attitude towards Serbia as a close American ally from both world wars. And what they did not know or understand at the time was this. They trampled Serbia, but they did not defeat it. Serbia rose like a phoenix from the ashes. And today through its example, it shows everyone in the world how the international public order is preserved and how international public law is protected. Nevertheless, the consequences of that brutal attack against Serbia are enormous and particularly visible here in the UN General Assembly."},{"t":495,"topic":"Croatia politics","text":"Admittedly, they are even more visible on the numerous battlefield battlefields around the world. Why? Well, because the principles of any kind no longer exist. Those who once trampled them have no moral right to speak about them. And to make the situation even worse and the hypocrisy even more visible, it is precisely those very people and those very countries who have assumed the position of supreme teacher of morale and every kind of protection of the values of the modern world. The most difficult thing for us in Serbia is when we see in our surroundings the resurgence of Nazism elevated to the position of social prominence, especially in the Republic of Croatia, which is proud of its Nazi past and one and of the use of Nazi slogans and symbols today. The Serbian people as people who suffer the most from Nazi hands cannot accept the revival of the most terrible ghosts from the past responsible for the death of hundreds of thousands of Serbs, Jews and Roma in mon in monstrous concentration camps like That is precisely why moral lectures coming from such sources are completely unacceptable to the Serbian people in Serbia."},{"t":567,"topic":"Kosovo status","text":"In addition, for four and a half years now, I have been listening to lectures. How many in the west remain last beacon of democracy in the world, the protectors not of Ukraine's but of the rules and principles of international law. And when they raise the their voices thinking that they are being highly moral and that their positions are the only right ones, we simply smile and ask ourselves. And how did you treat Kosovo and MKI and the territorial integrity of Serbia which is guaranteed by the UN charter and the resolution of the UN SC 1244 to that either there is no answer or there or they supposedly give us some well-intentioned advice and tell us not to look to the past but to the future. When we ask them do we also say to Ukraine that the territories they are fighting for are not important. we end the pointless conversation and move onto another subject. And I want to warn all of you, all of you here who belong to the global south, pay the utmost attention while signing all the agreements with great powers."},{"t":632,"topic":"Kosovo status","text":"That is how we signed the famous Brussels agreement in 12 in 2013, wishing to resolve problems between Serbs and Albanians in Kosovo and Mia by compromise. All the obligations that were to be met by Serbia have been met and the only one that was to be bet met by Albanians, the one about the establishment of the community of Serb municipalities has not been met to this day. It is interesting that the agreement was accepted not only in the presence of the EU but it was also confirmed with the signature of the EU but it meant actually nothing. As the president of Serbia for 10 years, I have been facing all possible tricks and pressures to give up on full implementation of what was signed. It is a lesson to us Serbs, but also to all others in the world who want to protect their country. In spite of everything, Serbia will defend its country, its territorial integrity, the UN charter, the UN Security Council resolution 1244. I wish to thank individually every of 107 countries states that has not recognized the unilaterally declared independence of the so-called Kosovo."},{"t":704,"topic":"Serbia EU integration","text":"We know that many of you that many of those states have been subjected to pressure and we know that maintaining a principled position is sometimes far more difficult than it appears from the outside. Thank you for being consistent in not recognizing the independence of a part of Serbia's territory. Serbia is on its European path and it will have to do many more things in order to become a full-fledged member of the EU. We are grateful to the European Union in and in particular to the president of the European Commission Ursula under Lion and to the president of the European Council Antonio Ka for every kind of assistance they have provided to our country. Although full-fledged membership to the European Union remains a strategic priority. We cannot ignore the prolonged enlargement fatigue both amongst certain EU member states and among the candidate countries themselves. Serbia's European path is a clear illustration of the length and complexity of this process."},{"t":767,"topic":"EU enlargement","text":"We obtained candidates titus in 2012 and opened accession negotiations in 2014, more than 12 years ago. The citizens of Serbia therefore rightly expect a clearer perspective and more tangible results from a process in which our country has participated for more than a decade. At a time when the next enlargement of the European Union does not appear likely in the near future, we have sought to remain constructive and to propose practical ways of overcoming the current impass. We have therefore proposed that the Western Balkans be gradually integrated into the EU single market and granted access to the Shenhen area even before attaining full membership in the EU. This would neither serve as a substitute for membership nor diminish our ambitions. Rather, it would provide a concrete and pragmatic way forward, enable the citizens and economies of the region to experience the tangible benefits of European integration, and help overcome the deadlock in which the enlargement process has remained for far too long. However, a stable and integrated Europe of which Serbia is a part and our European path do not mean renouncing the traditional friendship thanks to which Belgrade is one of the few European capitals from which one can fly directly to the United States of America, the People's Republic of China and the Russian Federation."},{"t":848,"topic":"China relations","text":"I owe special gratitude for the support during co pandemics as well as for a paramount investment in Serbia to the president of the people's republic of China Cining hoping that his talks with the President Trump will be productive and that they will contribute to the stabilization of the developments in the world. At the same time, we nurture ties with traditional friends and partners in Africa, Asia, and Latin America, with whom we recently marked in Belgrade the 65th anniversary of the first conference of non-aligned countries held in our capital in 1961. Our openness reflects our development strategy, our history, and our understanding of the world. Serbia believes that states can have a clear course and interests of their own without closing the door to those with whom they do not agree on everything. After all, a world in which we speak only to those who think as we do would have little need for diplomacy. Freedom and independence in making decisions are the highest value for Serbia."},{"t":913,"topic":"UN reform","text":"We must anticipate the consequences of a world in which force is once again being presented ever more openly as the most reliable instrument of policy in which military budgets are growing, conflicts are multiplying, arms control mechanisms are weakening and channels of communication are disappearing precisely when they are needed most. We must therefore ask the essential question where is the United Nations in such a The Security Council is often blocked precisely in the crisis in which it should be most active. Other parts of the UN system face financial pressures, overlapping mandates, bureaucratization, and the justified demand of member states to see more concrete results. These are real problems and there is no benefit in glossing over them. Yet, it by no means follows that we need the United Nations less. We may need it more than ever. It simply must be more effective, more focused, and more prepared to address the issues for which it was created. Over the past eight decades, states have not come to this building because they share the same interests, but because they understood that the cost of settling disagreements by force of arms was too high."},{"t":984,"topic":"UN reform","text":"That is why multilateralism came into being and why we are here today. Serbia supports the United Nations and reform of the UN system so that the organization may become more effective and better adapted to today's realities. We advocate a more representative UNC through greater representation of developing countries particularly those from the African continent as well as more inclusive regional representation and the addition of another seat for the Eastern European group. However, without a genuine return to the principles on which we have already agreed, I do not expect progress in terms of this organization's concrete results. Excellencies, peace is not the only test of our ability to many change. We are in the midst of a technological whose full reach we are only beginning to understand. Artificial intelligence is already changing the economy, education, medicine, security, the labor market, and the way states function."},{"t":1044,"topic":"Serbia technology","text":"It can bring enormous benefits to humanity. It can also deepen existing inequalities, enable new forms of manipulation, and create security risks that we could not even have imagined only a few years ago. During our during our leadership cycle in the global partnership of artificial intelligence which Serbia chaired in 2025, one of our priorities was to ensure the technological progress remained connected with security, human rights, the rule of law, accountability and bridging the digital divide. The Belgrade Ministerial Declaration received the support of 44 member states and the European Union and affirmed the need for safe, sustainable and human- centered artificial intelligence. The more powerful technology becomes, the more responsible those who manage it must be. We may have cutting edge algorithms, quantum computers, unmanned systems, and artificial intelligence capable of processing in a matter of seconds what once took us years."},{"t":1105,"topic":"Global order","text":"But if at the same time we allow the fundamental rules of the international order to be applied selectively, technological progress will not make the world safer. It will merely make us more technologically advanced in a world that is becoming politically less predictable. If we wish to manage the coming transformation responsibly, we must first reinforce the foundation on which the international order rests. Those foundations are simple. the sovereign equality of states, respect for territorial integrity, the prohibition of the use of forces except in the cases expressly provided for in the UN charter and the obligation not to change the rules from one case to another. Esteeemed colleagues, to those of you who know Serbia and our region, as well as those less familiar with this part of the world, I wish to express my gratitude to all who have honored Serbia by confirming their participation in the specialized Exhibition Expo 2027 to be held next year in Belgrade under the theme play for humanity, sport and music for all."},{"t":1170,"topic":"Serbia hosting","text":"Cultures, science, sport, technology, business and young people from all parts of the world will come together in Belgrade and I look forward to our hosting. A large number of the states represented in this hall today. At the outset, I spoke about trust and responsibility and that is where I wish to conclude. We will not restore trust through grand declarations if we then continue to act as before. Each of us must begin with our own decisions. Serbia endeavors to do so by preserving peace in its neighborhood, participating in peacekeeping missions far from its borders, assisting others when they are in danger, speaking even with those with whom it disagrees, and fulfilling the commitments it undertakes. What will restore trust in international law and in United Nations is more actions such as those. At the end, I thank you ladies and gentlemen. On behalf of the assembly, I wish to thank the President of the Republic of"}],"compare":[{"topic":"UN & its reform","share":0.2185,"mean":0.2047,"rank":79,"others":170},{"topic":"International Law & Order","share":0.1108,"mean":0.0601,"rank":41,"others":102},{"topic":"Europe","share":0.0654,"mean":0.0038,"rank":7,"others":8},{"topic":"NATO","share":0.0628,"mean":0.0015,"rank":3,"others":4},{"topic":"Serbia","share":0.0559,"mean":0.0008,"rank":3,"others":2},{"topic":"Russia-Ukraine War","share":0.0555,"mean":0.0352,"rank":42,"others":44},{"topic":"Global Economy","share":0.0521,"mean":0.0144,"rank":29,"others":31}]};
